class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        color = [0] * len(graph)

        def safe(u):
            if color[u]:
                return color[u] == 2
            color[u] = 1
            if all(safe(v) for v in graph[u]):
                color[u] = 2
                return True
            return False          # stays 1 -> unsafe

        return [u for u in range(len(graph)) if safe(u)]

